def coordonnees_vers_apparitions(apps, schema_editor):
    """
    Chaque lieu était rangé SOUS une carte, avec ses coordonnées : il devient
    une Apparition sur cette même carte, aux mêmes coordonnées. Rien n'est perdu.
    """
    LieuPage = apps.get_model('campagnes', 'LieuPage')
    CartePage = apps.get_model('campagnes', 'CartePage')
    Apparition = apps.get_model('campagnes', 'Apparition')
    for lieu in LieuPage.objects.all():
        # Arborescence Wagtail : le chemin du parent = le chemin du lieu
        # sans son dernier "segment" de 4 caractères.
        carte = CartePage.objects.filter(path=lieu.path[:-4]).first()
        if carte:
            Apparition.objects.create(carte=carte, lieu=lieu, coord_x=lieu.coord_x, coord_y=lieu.coord_y)


def apparitions_vers_coordonnees(apps, schema_editor):
    """Retour arrière : on remet sur le lieu les coordonnées de sa première apparition."""
    LieuPage = apps.get_model('campagnes', 'LieuPage')
    for lieu in LieuPage.objects.all():
        apparition = lieu.apparitions.order_by('sort_order', 'pk').first()
        if apparition:
            lieu.coord_x, lieu.coord_y = apparition.coord_x, apparition.coord_y
            lieu.save(update_fields=['coord_x', 'coord_y'])


